package ru.neverland.townyresearch.licenses;
import java.util.*;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.inventory.*;import org.bukkit.plugin.Plugin;import ru.neverland.core.*;import ru.neverland.townyresearch.service.ResearchService;
import static ru.neverland.townyresearch.licenses.TechLicense.Phase.*;
public final class LicenseMenu implements Listener{
 private final Plugin plugin;private final ResearchService research;private final LicenseService service;
 private static final class View implements InventoryHolder{final UUID viewer;final Map<Integer,Runnable> actions=new HashMap<>();Inventory inventory;View(UUID viewer){this.viewer=viewer;}public Inventory getInventory(){return inventory;}}
 public LicenseMenu(Plugin plugin,ResearchService research){this.plugin=plugin;this.research=research;service=research.licenses();}
 private boolean admin(Player p){return p.isOp()||p.hasPermission("neverlandtownyresearch.admin");}
 private boolean access(Player p,TechLicense row){var town=research.town(p);return admin(p)||p.hasPermission("neverlandtownyresearch.use")&&p.hasPermission("neverlandtownyresearch.licenses")&&town!=null&&Set.of(row.terms().seller(),row.terms().buyer()).contains(town.getUUID());}
 private View view(Player p,String name){var v=new View(p.getUniqueId());v.inventory=MenuStyle.inventory(plugin,v,54,name);return v;}
 public void open(Player p,int wanted){try(var guard=SuiteState.guard()){
  if(!admin(p)&&(!p.hasPermission("neverlandtownyresearch.use")||!p.hasPermission("neverlandtownyresearch.licenses")))throw new IllegalArgumentException("Нет доступа к лицензиям");var list=service.all().stream().filter(r->access(p,r)).sorted(Comparator.comparingLong(TechLicense::createdAt).reversed()).toList();int page=Math.max(0,Math.min(wanted,Math.max(0,(list.size()-1)/45)));var v=view(p,"Технологические лицензии");
  for(int i=page*45;i<Math.min(list.size(),(page+1)*45);i++){var row=list.get(i);button(v,i%45,row.phase()==PAY_REVIEW?Material.REDSTONE_BLOCK:row.phase()==ACTIVE?Material.ENCHANTED_BOOK:Material.BOOK,research.name(row.terms().technology())+" · "+status(row),lore(row),()->details(p,row.terms().id(),page,null));}
  if(page>0)button(v,45,Material.ARROW,"Предыдущая страница",List.of(),()->open(p,page-1));if((page+1)*45<list.size())button(v,53,Material.ARROW,"Следующая страница",List.of(),()->open(p,page+1));button(v,49,Material.SPYGLASS,"Обновить",List.of(service.availability(),"Страница "+(page+1)),()->open(p,page));button(v,47,Material.WRITABLE_BOOK,"Предложить технологию городу",List.of("Город должен сам изучить технологию.","Команда: /t research license offer","<город> <технология> <уровень> <монеты> <часы>","Покупатель отдельно подтвердит цену и срок.","Оплата поступит из его городской казны."),null);p.openInventory(v.inventory);
 }}
 public void details(Player p,UUID id,int page,String confirmation){try(var guard=SuiteState.guard()){
  var row=service.get(id);if(row==null||!access(p,row))throw new IllegalArgumentException("Лицензия не найдена или нет доступа");var v=view(p,confirmation==null?"Условия технологической лицензии":"Подтверждение условий");button(v,13,Material.ENCHANTED_BOOK,research.name(row.terms().technology())+" · "+status(row),lore(row),null);var own=research.town(p);boolean manager=own!=null&&research.manager(p,own)&&p.hasPermission("neverlandtownyresearch.licenses");
  if(confirmation==null){
   if(manager&&own.getUUID().equals(row.terms().buyer())&&row.phase()==OFFERED)button(v,29,Material.EMERALD,"Принять условия",List.of("Списание из статьи «Инфраструктура».","Бонус появится после подтверждения оплаты.","Следующий экран попросит подтверждение."),()->details(p,id,page,"accept"));
   if((manager||admin(p))&&Set.of(OFFERED,ACCEPTING,FUNDING,FUNDED).contains(row.phase()))button(v,33,Material.RED_DYE,"Отменить сделку",List.of("До выплаты продавцу — полный возврат.","Неопределённый платёж сначала нужно сверить."),()->details(p,id,page,"cancel"));
   if(admin(p)&&Set.of(ACTIVE,PAUSED).contains(row.phase()))button(v,31,Material.CLOCK,row.phase()==ACTIVE?"Приостановить лицензию":"Возобновить лицензию",List.of("На паузе бонус не действует и срок не расходуется."),()->details(p,id,page,"pause"));
   if(admin(p)&&row.phase()==PAY_REVIEW){button(v,29,Material.LIME_DYE,"Продавец точно получил оплату",List.of("Сначала проверьте ID и банковский журнал.","Далее потребуется подтверждение."),()->details(p,id,page,"paid"));button(v,33,Material.RED_DYE,"Продавец точно не получил оплату",List.of("После сверки покупателю вернётся полный резерв.","Текущий баланс не доказывает результат операции."),()->details(p,id,page,"unpaid"));}
  }else button(v,31,Material.LIME_DYE,"Подтверждаю: "+switch(confirmation){case "accept"->"принять цену и срок";case "cancel"->"отменить с полным возвратом";case "pause"->"изменить паузу";case "paid"->"продавец получил оплату";default->"выплаты продавцу не было";},List.of("Цена: "+money(row.terms().cents()),"Срок: "+time(row.terms().duration()),"Технология: "+research.name(row.terms().technology())+" "+row.terms().level(),"Решение относится только к этой лицензии."),()->{
   if(!access(p,row))throw new IllegalArgumentException("Доступ отозван");var latest=service.get(id);if(latest==null||latest.revision()!=row.revision()||latest.phase()!=row.phase())throw new IllegalStateException("Условия изменились; откройте лицензию заново");java.util.concurrent.CompletionStage<TechLicense> future;
   switch(confirmation){case "accept"->future=service.accept(p,id,row.revision());case "cancel"->future=service.cancel(p,id,row.revision());case "pause"->future=service.pause(p,id,row.revision());case "paid","unpaid"->{if(!admin(p))throw new IllegalArgumentException("Нужны права администратора");future=service.resolve(id,confirmation.equals("paid"),p);}default->throw new IllegalArgumentException("Неизвестное действие");}
   future.whenComplete((result,error)->{if(plugin.isEnabled())SuiteScheduler.entity(plugin,p,()->{if(!p.isOnline()||p.getOpenInventory().getTopInventory()!=v.inventory||!access(p,row))return;p.sendMessage(error==null?"Решение сохранено. Дождитесь подтверждения расчёта.":"Изменение пока не подтверждено; обновите лицензию.");details(p,id,page,null);});});p.sendMessage("Сохраняем ваше решение…");
  });
  button(v,45,Material.ARROW,"Назад",List.of(),()->{if(confirmation==null)open(p,page);else details(p,id,page,null);});button(v,49,Material.SPYGLASS,"Обновить",List.of(),()->details(p,id,page,null));p.openInventory(v.inventory);
 }}
 private List<String> lore(TechLicense r){var t=r.terms();return List.of("Продавец: "+town(t.seller()),"Покупатель: "+town(t.buyer()),"Уровень эффекта: "+t.level(),"Бонус: "+java.math.BigDecimal.valueOf(t.bonus()*100).stripTrailingZeros().toPlainString()+"%","Цена: "+money(t.cents()),"Оплаченный срок: "+time(t.duration()),r.phase()==OFFERED?"Предложение действует ещё: "+time(service.offerRemaining(r)):"Осталось оплаченного времени: "+time(service.remaining(r)),"Собственное исследование и его уровни не изменятся.","При паузе срок не расходуется.","ID: "+t.id(),r.note(),service.paymentNotice(r));}
 private static String money(long cents){return java.math.BigDecimal.valueOf(cents,2).toPlainString()+" монет";}private static String time(int seconds){return seconds/3600+" ч. "+seconds%3600/60+" мин. "+seconds%60+" сек.";}
 private static String town(UUID id){var t=com.palmergames.bukkit.towny.TownyAPI.getInstance().getTown(id);return t==null?id.toString():t.getName();}
 public static String status(TechLicense r){if(r.phase()==ACTIVE&&!r.audited())return "Подтверждается журнал оплаты";return switch(r.phase()){case OFFERED->"Предложение";case ACCEPTING->"Проверяется подтверждение покупателя";case FUNDING->"Подтверждается резерв казны";case FUNDED->"Подготовлена оплата продавцу";case PAYING->"Подтверждается выплата";case PAY_REVIEW->"Нужна сверка выплаты";case ACTIVE->"Действует";case PAUSED->"Приостановлена";case REFUNDING->"Возвращаются средства";case CANCELLED->"Отменена";case EXPIRED->"Срок завершён";case REJECTED->"Без оплаты";};}
 private void button(View v,int slot,Material icon,String title,List<String> lore,Runnable action){var stack=new ItemStack(icon);var meta=stack.getItemMeta();meta.setDisplayName(MenuStyle.nameLegacy("§f"+title));meta.setLore(MenuStyle.loreStrings(lore));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);stack.setItemMeta(meta);v.inventory.setItem(slot,stack);if(action!=null)v.actions.put(slot,action);}
 @EventHandler public void click(InventoryClickEvent e){try(var guard=SuiteState.guard()){if(!(e.getView().getTopInventory().getHolder() instanceof View v))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||!p.getUniqueId().equals(v.viewer)||e.getClick()!=ClickType.LEFT||e.getRawSlot()<0||e.getRawSlot()>=v.inventory.getSize()||SuiteState.frozen(plugin.getName()))return;var action=v.actions.get(e.getRawSlot());if(action!=null)SuiteScheduler.entity(plugin,p,()->{if(p.isOnline()&&p.getOpenInventory().getTopInventory()==v.inventory)try{action.run();}catch(RuntimeException error){p.sendMessage(error.getMessage());}});}}
 @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof View)e.setCancelled(true);}
}
